window.CODE = Object.assign(window.CODE || {}, {"ch20/dspy_basics.py":"\"\"\"DSPy basics: describe WHAT you want (a signature) and let DSPy write the prompt.\n\nSignature  inputs -> outputs, with types and short descriptions\nModule     a strategy for producing the outputs: Predict (direct), ChainOfThought (reason first), ReAct (tools)\n\nRun:  pip install -r requirements-dspy.txt      (in its own virtual environment; see the note in the lesson)\n      python dspy_basics.py\n\"\"\"\nimport os\nfrom typing import Literal\n\nimport dspy\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n\ndef make_lm() -> dspy.LM:\n    \"\"\"DSPy names models as 'provider/model'. Keys come from OPENAI_API_KEY / ANTHROPIC_API_KEY.\"\"\"\n    if os.getenv(\"PROVIDER\", \"openai\") == \"anthropic\":\n        return dspy.LM(f\"anthropic/{os.getenv('ANTHROPIC_MODEL', 'claude-haiku-5-5')}\", temperature=0, max_tokens=600)\n    return dspy.LM(f\"openai/{os.getenv('OPENAI_MODEL', 'gpt-4.1-mini')}\", temperature=0, max_tokens=600)\n\n\nclass Triage(dspy.Signature):\n    \"\"\"Classify a patient message sent to the City Clinic helpdesk.\"\"\"\n\n    message: str = dspy.InputField()\n    intent: Literal[\"schedule\", \"billing\", \"reports\", \"emergency\", \"other\"] = dspy.OutputField()\n    urgent: bool = dspy.OutputField(desc=\"True for chest pain, breathing trouble, heavy bleeding or unconsciousness\")\n\n\nif __name__ == \"__main__\":\n    dspy.configure(lm=make_lm())\n\n    triage = dspy.Predict(Triage)\n    result = triage(message=\"Which days does Dr Rao see patients?\")\n    print(\"Predict:        \", result.intent, result.urgent)\n\n    # A signature can also be a short string: \"inputs -> outputs\"\n    summarise = dspy.Predict(\"discharge_note -> summary_for_patient: str\")\n    print(\"String sig:     \", summarise(discharge_note=\"Pt stable. Continue tab X 1-0-1 x5d. Review OPD 1 wk.\").summary_for_patient)\n\n    think = dspy.ChainOfThought(Triage)              # adds a 'reasoning' output before the others\n    result = think(message=\"My father is sweating and has pain in his chest\")\n    print(\"ChainOfThought: \", result.intent, result.urgent)\n    print(\"  reasoning:    \", result.reasoning)\n\n    print(\"\\nThe prompt DSPy wrote for the last call:\")\n    dspy.inspect_history(n=1)\n","ch20/dspy_modules.py":"\"\"\"Composing DSPy modules: a small RAG program, and a ReAct agent with a tool.\n\nA dspy.Module is like a PyTorch module: sub-modules in __init__, the flow in forward().\nOptimisers can then tune every sub-module's prompt together.\n\nRun:  python dspy_modules.py\n\"\"\"\nimport re\nimport sys\nfrom pathlib import Path\n\nimport dspy\nfrom dspy_basics import make_lm\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import get_doctor_schedule  # noqa: E402\n\nSECTIONS = [s.strip() for p in sorted((HERE.parent / \"ch07\" / \"docs\").glob(\"*.md\"))\n            for s in re.split(r\"\\n(?=## )\", p.read_text(encoding=\"utf-8\"))[1:]]\n\n\ndef keyword_search(query: str, k: int = 2) -> list[str]:\n    \"\"\"A tiny keyword retriever, to keep this example self-contained. Use real search in practice.\"\"\"\n    words = set(re.findall(r\"[a-z0-9]+\", query.lower()))\n    return sorted(SECTIONS, key=lambda s: -len(words & set(re.findall(r\"[a-z0-9]+\", s.lower()))))[:k]\n\n\nclass ClinicRAG(dspy.Module):\n    def __init__(self):\n        super().__init__()\n        self.answer = dspy.ChainOfThought(\"context: list[str], question -> answer\")\n\n    def forward(self, question: str):\n        context = keyword_search(question)\n        return self.answer(context=context, question=question)\n\n\nif __name__ == \"__main__\":\n    dspy.configure(lm=make_lm())\n\n    rag = ClinicRAG()\n    print(\"RAG:  \", rag(question=\"Can children visit the ICU?\").answer)\n\n    # dspy.ReAct: give it a signature and plain Python tools; it runs the think-act-observe loop\n    agent = dspy.ReAct(\"question -> answer\", tools=[get_doctor_schedule], max_iters=4)\n    result = agent(question=\"Which days does the orthopaedics doctor work?\")\n    print(\"ReAct:\", result.answer)\n    print(\"Steps:\", [v for k, v in result.trajectory.items() if k.startswith(\"tool_name\")])\n","ch20/dspy_optimize.py":"\"\"\"Optimise a DSPy program: measure it, let an optimiser improve the prompt, measure again.\n\nmetric      a Python function: was this prediction right?\nEvaluate    runs the program on a dev set and scores it\noptimiser   BootstrapFewShot runs the program on training examples, keeps the runs that pass the\n            metric, and adds them to the prompt as worked examples (demos)\n\nRun:  python dspy_optimize.py\n\"\"\"\nimport json\nfrom pathlib import Path\n\nimport dspy\nfrom dspy_basics import Triage, make_lm\n\nHERE = Path(__file__).resolve().parent\ndata = json.loads((HERE / \"triage_data.json\").read_text())\ntrainset = [dspy.Example(message=m, intent=i).with_inputs(\"message\") for m, i in data[\"train\"]]\ndevset = [dspy.Example(message=m, intent=i).with_inputs(\"message\") for m, i in data[\"dev\"]]\n\n\ndef intent_match(example, prediction, trace=None) -> bool:\n    \"\"\"The metric: does the predicted intent match the label? (Return a float for partial credit.)\"\"\"\n    return prediction.intent == example.intent\n\n\nif __name__ == \"__main__\":\n    dspy.configure(lm=make_lm())\n    evaluate = dspy.Evaluate(devset=devset, metric=intent_match, num_threads=4)\n\n    program = dspy.Predict(Triage)\n    before = evaluate(program)\n    print(f\"Before optimising: {before.score:.0f}% on {len(devset)} dev examples\")\n\n    optimiser = dspy.BootstrapFewShot(metric=intent_match, max_bootstrapped_demos=4, max_labeled_demos=16)\n    optimised = optimiser.compile(program, trainset=trainset)\n    after = evaluate(optimised)\n    print(f\"After optimising:  {after.score:.0f}%  ({len(optimised.demos)} examples added to the prompt)\")\n\n    for ex, pred, ok in after.results:\n        if not ok:\n            print(f\"  still wrong: {ex.message!r} -> {pred.intent} (expected {ex.intent})\")\n\n    optimised.save(str(HERE / \"triage_optimised.json\"))          # reload with program.load(...)\n    print(\"Saved the optimised program to triage_optimised.json\")\n","ch20/requirements-dspy.txt":"# DSPy in its OWN virtual environment: dspy 3.4 depends on litellm, which needs openai < 3,\n# while the rest of the course uses openai 3.x.\n#   python -m venv .venv-dspy && source .venv-dspy/bin/activate && pip install -r requirements-dspy.txt\ndspy==3.4.1\npython-dotenv>=1.0\n","ch20/triage_data.json":"{\"train\": [\n [\"Which days does Dr Mehta see patients?\", \"schedule\"],\n [\"Is the orthopaedics doctor in on Tuesday?\", \"schedule\"],\n [\"When can I meet the child specialist?\", \"schedule\"],\n [\"I was charged twice for my ECG\", \"billing\"],\n [\"Can I get an itemised bill for my stay?\", \"billing\"],\n [\"Is the OPD fee refundable?\", \"billing\"],\n [\"Are my blood test results ready?\", \"reports\"],\n [\"How do I download my MRI report?\", \"reports\"],\n [\"I need a copy of my discharge summary\", \"reports\"],\n [\"My mother collapsed and is not responding\", \"emergency\"],\n [\"He is having trouble breathing\", \"emergency\"],\n [\"Is there parking for two-wheelers?\", \"other\"],\n [\"Can I bring food for my father in the ward?\", \"other\"],\n [\"Do you have a pharmacy open at night?\", \"other\"],\n [\"Can I pay the bill by UPI?\", \"billing\"],\n [\"When will my X-ray report be ready?\", \"reports\"],\n [\"Has my scan result come?\", \"reports\"],\n [\"My son swallowed a coin\", \"emergency\"]\n],\n\"dev\": [\n [\"Which day is Dr Khan available?\", \"schedule\"],\n [\"Does Dr Iyer work on Thursdays?\", \"schedule\"],\n [\"Why is there a Rs 350 charge on my invoice?\", \"billing\"],\n [\"How do I pay my hospital dues online?\", \"billing\"],\n [\"Where can I collect my X-ray films?\", \"reports\"],\n [\"My lab report shows high sugar, can I get the PDF?\", \"reports\"],\n [\"Has my biopsy result come?\", \"reports\"],\n [\"My child swallowed a battery\", \"emergency\"],\n [\"Severe bleeding after a fall\", \"emergency\"],\n [\"Is Wi-Fi available in the waiting area?\", \"other\"]\n]}\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
